<template>
  <div class="workflow-view">
    <header class="page-heading"><div><div class="eyebrow">AUTOMATION</div><h1>工作流</h1><p>把文档接收、智能处理、规则校验和人工复核组合成可复用流程。</p></div><button class="primary-btn" @click="openCreate">＋ 新建工作流</button></header>
    <section class="guide-strip"><div><span>1</span><p><strong>定义处理步骤</strong><small>选择业务需要的节点</small></p></div><b>→</b><div><span>2</span><p><strong>配置校验规则</strong><small>约束关键字段质量</small></p></div><b>→</b><div><span>3</span><p><strong>发布并运行</strong><small>形成标准处理链路</small></p></div></section>
    <section class="workflow-card">
      <div class="section-head"><div><h2>我的工作流</h2><p>{{ workflows.length }} 个流程，{{ activeCount }} 个已启用</p></div><button class="text-btn" @click="loadWorkflows">刷新</button></div>
      <div v-if="loading" class="empty">正在加载...</div>
      <div v-else-if="!workflows.length" class="empty"><span>⌘</span><strong>还没有工作流</strong><p>创建一条流程，把重复的文档操作沉淀为标准能力。</p><button class="text-btn" @click="openCreate">创建第一条工作流</button></div>
      <div v-else class="workflow-grid">
        <article v-for="item in workflows" :key="item.id" class="workflow-item">
          <div class="item-head"><div class="workflow-icon">⌘</div><span class="status" :class="item.status">{{ statusText[item.status] }}</span></div>
          <h3>{{ item.name }}</h3><p>{{ item.description || '暂无流程说明' }}</p>
          <div class="node-preview"><template v-for="(node,index) in item.nodes.slice(0,5)" :key="node.id || index"><span>{{ node.label || node.type }}</span><b v-if="index<Math.min(item.nodes.length,5)-1">→</b></template><small v-if="!item.nodes.length">尚未配置节点</small></div>
          <div class="item-meta"><span>v{{ item.version }}</span><span>{{ item.rules.length }} 条规则</span><span>运行 {{ item.runs_count }} 次</span></div>
          <div class="item-actions"><button @click="edit(item)">编辑</button><button @click="toggle(item)">{{ item.status==='active'?'暂停':'启用' }}</button><button class="danger" @click="remove(item)">删除</button></div>
        </article>
      </div>
    </section>

    <div v-if="showEditor" class="modal-mask" @click.self="showEditor=false"><div class="modal-card">
      <div class="modal-head"><div><h2>{{ editingId?'编辑工作流':'新建工作流' }}</h2><p>第一版采用明确的顺序节点，便于稳定执行和审计。</p></div><button @click="showEditor=false">×</button></div>
      <div class="form-row"><label><span>工作流名称</span><input v-model.trim="form.name" placeholder="例如：采购合同信息审核" /></label><label><span>流程说明</span><input v-model.trim="form.description" placeholder="说明适用的业务场景" /></label></div>
      <div class="editor-section"><div class="editor-title"><strong>处理节点</strong><span>点击节点添加或移除</span></div><div class="node-options"><button v-for="node in availableNodes" :key="node.type" :class="{selected:form.nodeTypes.includes(node.type)}" @click="toggleNode(node.type)"><b>{{ node.icon }}</b><span>{{ node.label }}</span><small>{{ node.desc }}</small></button></div><div class="selected-flow"><template v-for="(type,index) in form.nodeTypes" :key="type"><span>{{ nodeByType(type).label }}</span><b v-if="index<form.nodeTypes.length-1">→</b></template></div><label v-if="form.nodeTypes.includes('extract')" class="field-config"><span>需要提取的字段</span><input v-model.trim="form.extractFields" placeholder="例如：合同编号,甲方,合同金额,签署日期" /><small>多个字段使用逗号分隔，运行工作流前必须配置。</small></label></div>
      <div class="editor-section"><div class="editor-title"><strong>字段校验规则</strong><button class="text-btn" @click="addRule">＋ 添加规则</button></div><div v-if="!form.rules.length" class="rule-empty">暂未配置规则。复核中心仍会执行空值、置信度和证据检查。</div><div v-for="(rule,index) in form.rules" :key="index" class="rule-row"><input v-model.trim="rule.field" placeholder="字段名" /><select v-model="rule.type"><option value="required">必填</option><option value="regex">格式匹配</option><option value="min">最小值</option><option value="max">最大值</option></select><input v-if="rule.type!=='required'" v-model="rule.value" :placeholder="rule.type==='regex'?'正则表达式':'校验值'" /><input v-model.trim="rule.message" placeholder="失败提示" /><button @click="form.rules.splice(index,1)">×</button></div></div>
      <div class="modal-actions"><button class="secondary-btn" @click="showEditor=false">取消</button><button class="primary-btn" :disabled="saving||form.name.length<2||!form.nodeTypes.length" @click="save">{{ saving?'正在保存...':'保存工作流' }}</button></div>
    </div></div>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { createWorkflow, deleteWorkflow, getWorkflows, updateWorkflow } from '../../api/workspace'
const loading=ref(true),saving=ref(false),workflows=ref([]),showEditor=ref(false),editingId=ref(null)
const form=reactive({name:'',description:'',nodeTypes:[],extractFields:'',rules:[]})
const statusText={draft:'草稿',active:'已启用',paused:'已暂停'}
const availableNodes=[{type:'intake',label:'文档接收',desc:'接收并归档材料',icon:'⇧'},{type:'classify',label:'自动分类',desc:'识别文档业务类型',icon:'◇'},{type:'extract',label:'信息提取',desc:'生成结构化字段',icon:'⌁'},{type:'validate',label:'规则校验',desc:'执行确定性检查',icon:'✓'},{type:'review',label:'人工复核',desc:'处理异常与低置信度',icon:'◎'},{type:'export',label:'结果交付',desc:'导出或回写数据',icon:'⇥'}]
const activeCount=computed(()=>workflows.value.filter(i=>i.status==='active').length),nodeByType=(type)=>availableNodes.find(i=>i.type===type)||{label:type}
const loadWorkflows=async()=>{loading.value=true;try{workflows.value=(await getWorkflows()).items}catch(e){alert(e.message)}finally{loading.value=false}}
const reset=()=>{editingId.value=null;Object.assign(form,{name:'',description:'',nodeTypes:['intake','extract','validate','review','export'],extractFields:'',rules:[]})}
const openCreate=()=>{reset();showEditor.value=true}
const edit=(item)=>{editingId.value=item.id;const extractNode=item.nodes.find(n=>n.type==='extract');Object.assign(form,{name:item.name,description:item.description,nodeTypes:item.nodes.map(n=>n.type),extractFields:(extractNode?.fields||[]).join(','),rules:JSON.parse(JSON.stringify(item.rules||[]))});showEditor.value=true}
const toggleNode=(type)=>{const index=form.nodeTypes.indexOf(type);if(index>=0)form.nodeTypes.splice(index,1);else form.nodeTypes.push(type)}
const addRule=()=>form.rules.push({field:'',type:'required',value:'',message:'该字段不能为空',level:'error'})
const save=async()=>{saving.value=true;try{const rules=form.rules.map(r=>({...r,pattern:r.type==='regex'?r.value:undefined}));const fields=form.extractFields.replaceAll('，',',').split(',').map(i=>i.trim()).filter(Boolean);const payload={name:form.name,description:form.description,nodes:form.nodeTypes.map((type,index)=>({id:`node-${index+1}`,type,label:nodeByType(type).label,order:index+1,...(type==='extract'?{fields}:{})})),rules};if(editingId.value)await updateWorkflow(editingId.value,payload);else await createWorkflow(payload);showEditor.value=false;await loadWorkflows()}catch(e){alert(e.message)}finally{saving.value=false}}
const toggle=async(item)=>{try{await updateWorkflow(item.id,{status:item.status==='active'?'paused':'active'});await loadWorkflows()}catch(e){alert(e.message)}}
const remove=async(item)=>{if(!confirm(`确定删除工作流“${item.name}”吗？`))return;try{await deleteWorkflow(item.id);await loadWorkflows()}catch(e){alert(e.message)}}
onMounted(loadWorkflows)
</script>

<style scoped>
