rder-radius:10px;background:#f0e5d4;color:#a67634;display:grid;place-items:center;font:19px system-ui}.status{height:25px;padding:0 9px;border-radius:12px;background:#eee;color:#777;display:flex;align-items:center;font-size:11px}.status.active{background:#e5f4eb;color:#48805b}.status.paused{background:#fff0d8;color:#a86b18}.workflow-item h3{font-size:17px;margin:14px 0 6px}.workflow-item>p{font-size:13px;color:#8c857d;min-height:21px;margin:0}.node-preview{height:66px;margin:15px 0;background:#f7f4ef;border-radius:10px;padding:12px;display:flex;align-items:center;gap:6px;overflow:hidden}.node-preview span{padding:6px 7px;border-radius:6px;background:#fff;border:1px solid #e2dbd0;font-size:11px;white-space:nowrap}.node-preview b{font:12px system-ui;color:#b9a98f}.node-preview small{color:#aaa}.item-meta{display:flex;gap:15px;font-size:11px;color:#a29a91;padding-bottom:14px;border-bottom:1px solid #ece9e4}.item-actions{display:flex;gap:15px;padding-top:13px}.item-actions button{border:0;background:none;color:#9a6c2e;cursor:pointer;font-family:inherit;padding:0}.item-actions .danger{color:#bf6960}.modal-mask{position:fixed;inset:0;background:rgba(30,27,23,.45);z-index:200;display:grid;place-items:center;padding:20px}.modal-card{width:900px;max-width:100%;max-height:92vh;overflow:auto;background:#fafafa;border-radius:20px;padding:27px;box-shadow:0 25px 70px rgba(0,0,0,.22)}.modal-head{display:flex;justify-content:space-between}.modal-head h2{margin:0 0 6px;font-size:22px}.modal-head>button{border:0;background:#eee8df;border-radius:50%;width:34px;height:34px;font-size:22px;color:#777;cursor:pointer}.form-row{display:grid;grid-template-columns:1fr 1.4fr;gap:14px;margin:22px 0}.form-row label{display:grid;gap:7px;color:#686159;font-size:13px}.form-row input,.rule-row input,.rule-row select{height:42px;border:1px solid #ddd6cd;border-radius:9px;padding:0 11px;outline:0;background:#fff;font-family:inherit}.editor-section{border-top:1px solid #e4dfd7;padding:19px 0}.editor-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:13px}.editor-title span{font-size:12px;color:#999}.node-options{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.node-options button{min-height:76px;border:1px solid #ddd7ce;border-radius:10px;background:#fff;display:grid;grid-template-columns:30px 1fr;gap:3px 8px;text-align:left;padding:11px;cursor:pointer;font-family:inherit}.node-options button.selected{border-color:#c99e5d;background:#faf3e7;box-shadow:inset 0 0 0 1px #d9b77f}.node-options b{grid-row:1/3;width:29px;height:29px;border-radius:8px;background:#eee6da;display:grid;place-items:center;color:#a57839}.node-options span{font-size:13px;font-weight:700}.node-options small{color:#9c958c}.selected-flow{min-height:52px;margin-top:12px;border-radius:9px;background:#f1ede7;display:flex;align-items:center;gap:7px;padding:10px;overflow:auto}.selected-flow span{background:#fff;border:1px solid #ded7cc;padding:7px 9px;border-radius:7px;font-size:12px;white-space:nowrap}.selected-flow b{font:12px system-ui;color:#baa98e}.field-config{display:grid;gap:7px;margin-top:12px;color:#686159;font-size:13px}.field-config input{height:42px;border:1px solid #ddd6cd;border-radius:9px;padding:0 11px;outline:0;background:#fff;font-family:inherit}.field-config small{color:#9c958c}.rule-empty{height:55px;border:1px dashed #d8d1c7;border-radius:9px;display:grid;place-items:center;color:#aaa;font-size:12px}.rule-row{display:grid;grid-template-columns:1fr 120px 1fr 1.4fr 32px;gap:8px;margin-bottom:8px}.rule-row>button{border:0;background:#f1e2df;color:#ac5c53;border-radius:8px;cursor:pointer}.modal-actions{display:flex;justify-content:flex-end;gap:10px;padding-top:6px}@media(max-width:1000px){.workflow-grid{grid-template-columns:1fr}.node-options{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.page-heading{flex-direction:column;align-items:flex-start;gap:16px}.guide-strip{justify-content:flex-start;overflow:auto}.guide-strip>b{display:none}.workflow-grid,.form-row,.node-options{grid-template-columns:1fr}.rule-row{grid-template-columns:1fr 110px}.rule-row input:nth-of-type(2){grid-column:1/-1}.rule-row>button{min-height:34px}}
</style>
